def icon(name='arrow',cls=''):
 paths={
 'arrow':'<path d="M5 12h14M13 6l6 6-6 6"/>',
 'up':'<path d="M6 18 18 6M6 6h12v12"/>',
 'down':'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
 'search':'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
 'plus':'<path d="M12 5v14M5 12h14"/>',
 'close':'<path d="m6 6 12 12M6 18 18 6"/>',
 'mail':'<rect x="3" y="5" width="18" height="14" rx="1"/><path d="m3 5 9 8 9-8"/>',
 'chip':'<rect x="6" y="6" width="12" height="12" rx="1"/><path d="M9 1v5m6-5v5M9 18v5m6-5v5M1 9h5m-5 6h5m12-6h5m-5 6h5"/><path d="M10 10h4v4h-4z"/>',
 'wave':'<path d="M1 12h3l3-8 5 16 5-16 3 8h3"/>',
 'layers':'<path d="m2 8 10-5 10 5-10 5L2 8Zm0 5 10 5 10-5M2 18l10 5 10-5"/>',
 'menu':'<path d="M3 6h18M3 12h18M3 18h18"/>',
 'check':'<path d="m5 12 4 4L19 6"/>'}
 return f'<svg class="icon {cls}" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">{paths[name]}</svg>'

