def header(active=''):
 return f'''<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="nav-wrap">{brand()}<nav class="desktop-nav" aria-label="Main navigation"><a class="{'active' if active=='products' else ''}" href="/products/">Products</a><a class="{'active' if active=='capabilities' else ''}" href="/capabilities/">Capabilities</a><a class="{'active' if active=='applications' else ''}" href="/applications/">Applications</a><a class="{'active' if active=='company' else ''}" href="/company/">Company</a><a class="{'active' if active=='resources' else ''}" href="/resources/">Resources</a></nav><div class="nav-actions"><button class="search-open" aria-label="Search products">{icon('search')}</button><a class="button small button-outline nav-contact" href="/contact/">Let’s talk {icon('up')}</a><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="mobile-nav">{icon('menu')}</button></div></div><nav id="mobile-nav" class="mobile-nav" aria-label="Mobile navigation" hidden><a href="/products/">Products</a><a href="/capabilities/">Capabilities</a><a href="/applications/">Applications</a><a href="/company/">Company</a><a href="/resources/">Resources</a><a href="/contact/">Contact</a></nav></header>'''

