def overlays():return f'''<dialog id="search-dialog" class="search-dialog"><div class="dialog-top"><span class="eyebrow">FIND YOUR PLATFORM</span><button class="dialog-close" aria-label="Close search">{icon('close')}</button></div><label class="global-search">{icon('search')}<input id="global-search" type="search" placeholder="Search RFSoC, Versal, 3U…" autocomplete="off" aria-label="Search product catalogue"></label><p class="search-hint">Search by platform, form factor, or application.</p><div id="search-results" aria-live="polite"></div></dialog><div id="toast" role="status" aria-live="polite"></div>'''

def layout(body,title,desc,active='',page=''):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#ffffff"><title>{e(title)} | Avarthana Technologies</title><meta name="description" content="{e(desc)}"><link rel="icon" href="/assets/round-logo.png"><link rel="stylesheet" href="/assets/fonts/fonts.css"><link rel="stylesheet" href="/assets/style.css"><script src="/assets/app.js" defer></script></head><body id="top" data-page="{page}">{header(active)}<main id="main">{body}</main>{footer()}{overlays()}</body></html>'''
def save(path,content):
 out=DIST/path;out.parent.mkdir(parents=True,exist_ok=True);out.write_text(content)
def link_product(p):return '/products/'+p['slug']+'/'
def product_card(p):
 tags=f'<span>{e(p["form"])}</span><span>{e(p["family"])}</span>'
 short=f'{p["channels"]} Rx / {p["channels"]} Tx' if p['channels'] else ('13-card configuration' if p['id'] in (13,14) else p['processor'])
 return f'''<article class="product-card" data-id="{p['id']}" data-category="{e(p['category'])}" data-form="{e(p['form'])}" data-family="{e(p['family'])}" data-search="{e((' '.join([p['title'],p['subtitle'],p['summary'],p['processor'],p['category']])).lower())}"><div class="product-visual"><div class="product-tags">{tags}</div><a href="{link_product(p)}" aria-label="View {e(p['title']+' '+p['subtitle'])}"><img src="{p['image']}" alt="{e(p['title'])} hardware render" loading="lazy" width="700" height="440"></a></div><div class="product-card-body"><p class="eyebrow">{e(p['subtitle'])}</p><h3><a href="{link_product(p)}">{e(p['title'])}</a></h3><p>{e(p['summary'])}</p><div class="product-card-foot"><span>{e(short)}</span><a href="{link_product(p)}" aria-label="Explore {e(p['title']+' '+p['subtitle'])}">{icon('arrow')}</a></div></div></article>'''

